import{_ as e,c as a,a2 as o,o as r}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第二百三十九章 从快乐喜悦中解脱出来","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/239第二百三十九章 从快乐喜悦中解脱出来.md","filePath":"meditation/巴利文大藏经/239第二百三十九章 从快乐喜悦中解脱出来.md"}'),n={name:"meditation/巴利文大藏经/239第二百三十九章 从快乐喜悦中解脱出来.md"};function _(p,t,s,i,d,c){return r(),a("div",null,t[0]||(t[0]=[o('<h1 id="第二百三十九章-从快乐喜悦中解脱出来" tabindex="-1">第二百三十九章 从快乐喜悦中解脱出来 <a class="header-anchor" href="#第二百三十九章-从快乐喜悦中解脱出来" aria-label="Permalink to &quot;第二百三十九章 从快乐喜悦中解脱出来&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部22相应28经/乐味经第三(蕴相应/蕴篇/修多罗)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，佛陀对出家弟子们说：“比丘们（出家人）！如果物质事物、物质身体、感受、念想、行为、认识、分别、判断不能让世间的众生产生快乐、喜悦，那么世间的众生也不会贪爱、沉迷于物质事物、物质身体、感受、念想、行为、认识、分别、判断之中。比丘们！就是因为物质事物、物质身体、感受、念想、行为、认识、分别、判断能让世间的众生产生快乐、喜悦，所以世间的众生才会贪爱、沉迷于物质事物、物质身体、感受、念想、行为、认识、分别、判断之中。</p><p>比丘们！如果物质事物、物质身体、感受、念想、行为、认识、分别、判断能够永远存在，能够永远拥有，能够永恒保持不变，那么就不会给世间的众生带来痛苦。比丘们！就是因为物质事物、物质身体、感受、念想、行为、认识、分别、判断无法永远存在，无法永远拥有，无法永恒保持不变，所以才会最终给世间的众生带来痛苦。</p><p>比丘们！如果沉迷于物质事物、物质身体、感受、念想、行为、认识、分别、判断的欲望、贪爱中，就能从物质事物、物质身体、感受、念想、行为、认识、分别、判断中解脱出来，就能从烦恼和痛苦中解脱出来，那么世间的众生就不会去修习除灭、熄灭贪欲的解脱法。比丘们！就是因为要降伏熄灭对物质事物、物质身体、感受、念想、行为、认识、分别、判断的欲望、贪爱，要除灭舍断对物质事物、物质身体、感受、念想、行为、认识、分别、判断的欲望、贪爱，要不执着和挂念物质事物、物质身体、感受、念想、行为、认识、分别、判断，才能从物质事物、物质身体、感受、念想、行为、认识、分别、判断中解脱出来，才能从烦恼和痛苦中解脱出来，所以世间的众生才会去修习除灭、熄灭贪欲的解脱法。</p><p>比丘们！只要世间的众生不能证悟得知：「沉迷于物质事物、物质身体、感受、念想、行为、认识、分别、判断的<strong>滋味是什么</strong>？物质事物、物质身体、感受、念想、行为、认识、分别、判断的<strong>祸患是什么</strong>？如何从物质事物、物质身体、感受、念想、行为、认识、分别、判断<strong>中解脱出来</strong>？（物质事物、物质身体、感受、念想、行为、认识、分别、判断的沉迷滋味、祸患、解脱解释，见第二百三十八章）」那么世间的众生就无法从人界、天界、魔界、梵天界等等所处的界中解脱出来。世间的普通人、出家人、修行人、天神、魔王、梵天王等等一切的众生也无法从世间的束缚捆绑中解脱出来，他们无法从自己的各种念想中解脱出来。</p><p>比丘们！当世间的众生证悟得知：「沉迷于物质事物、物质身体、感受、念想、行为、认识、分别、判断的滋味是什么？物质事物、物质身体、感受、念想、行为、认识、分别、判断的祸患是什么？如何从物质事物、物质身体、感受、念想、行为、认识、分别、判断中解脱出来？（物质事物、物质身体、感受、念想、行为、认识、分别、判断的沉迷滋味、祸患、解脱解释，见第二百三十八章）」世间的众生就能从人界、天界、魔界、梵天界等等所处的界中解脱出来。世间的普通人、出家人、修行人、天神、魔王、梵天王等等一切的众生就能从世间的束缚捆绑中解脱出来，他们就能从自己的各种念想中解脱出来。”</p><p>佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。</p>',9)]))}const f=e(n,[["render",_]]);export{m as __pageData,f as default};
